import pandas as pd
import numpy as np
from pathlib import Path

input_path = Path('/root/environment/data/ckd_lab_data.csv')
ref_path = Path('/root/.codex/skills/lab-unit-harmonization/reference/ckd_lab_features.md')
output_path = Path('/root/ckd_lab_data_harmonized.csv')

# Load raw data as strings to preserve formatting
raw_df = pd.read_csv(input_path, dtype=str)

numeric_cols = [c for c in raw_df.columns if c != 'patient_id']

missing_markers = {'', 'nan', 'none', 'null', 'na', 'n/a', 'nan ', ' none', 'null ', '-999', '-999.0'}


def parse_value(value):
    if value is None or (isinstance(value, float) and np.isnan(value)):
        return np.nan
    s = str(value).strip()
    if s.lower() in missing_markers:
        return np.nan

    # Remove internal spaces
    s = s.replace(' ', '')

    # Handle commas: if both comma and dot present, assume commas are thousands separators
    if ',' in s and '.' in s:
        s = s.replace(',', '')
    elif ',' in s:
        s = s.replace(',', '.')

    # Parse to float (handles scientific notation)
    try:
        return float(s)
    except ValueError:
        return np.nan


# Parse numeric columns
parsed_df = raw_df.copy()
for col in numeric_cols:
    parsed_df[col] = parsed_df[col].apply(parse_value)

# Drop rows with any missing numeric values
before_rows = len(parsed_df)
parsed_df = parsed_df.dropna(subset=numeric_cols).reset_index(drop=True)
after_rows = len(parsed_df)

# Load reference ranges from markdown

def load_reference_ranges(md_path):
    ranges = {}
    with open(md_path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line.startswith('|'):
                continue
            if '---' in line:
                continue
            parts = [p.strip() for p in line.strip('|').split('|')]
            if len(parts) < 7:
                continue
            key = parts[0]
            try:
                min_val = float(parts[3])
                max_val = float(parts[4])
            except ValueError:
                continue
            ranges[key] = (min_val, max_val)
    return ranges


reference_ranges = load_reference_ranges(ref_path)

# Conversion factors (multiply by factor to convert to US conventional units)
conversion_factors = {
    'Serum_Creatinine': [0.0113],
    'BUN': [2.8],
    'Magnesium': [2.43, 1.2146],
    'Serum_Calcium': [4.0, 2.0],
    'Ionized_Calcium': [0.25],
    'Phosphorus': [3.1],
    'Intact_PTH': [9.43],
    'Vitamin_D_25OH': [0.4],
    'Vitamin_D_1_25OH': [0.385],
    'Hemoglobin': [0.1, 1.611],
    'Hematocrit': [100.0],
    'Serum_Iron': [5.59],
    'TIBC': [5.59],
    'Ferritin': [0.445],
    'Reticulocyte_Count': [100.0],
    'Total_Bilirubin': [0.058],
    'Direct_Bilirubin': [0.058],
    'Albumin_Serum': [0.1],
    'Total_Protein': [0.1],
    'Prealbumin': [0.1, 100.0],
    'CRP': [10.0],
    'Total_Cholesterol': [38.67],
    'LDL_Cholesterol': [38.67],
    'HDL_Cholesterol': [38.67],
    'Triglycerides': [88.5],
    'Non_HDL_Cholesterol': [38.67],
    'Glucose': [18.02],
    'Uric_Acid': [0.0168],
    'Urine_Albumin': [10.0],
    'Urine_Creatinine': [0.0113, 0.113],
    'Albumin_to_Creatinine_Ratio_Urine': [8.84],
    'Protein_to_Creatinine_Ratio_Urine': [8.84],
    'Urine_Protein': [0.1],
    'Urine_Specific_Gravity': [0.001],
    'BNP': [3.46],
    'NT_proBNP': [8.47],
    'Troponin_I': [0.001],
    'Troponin_T': [0.001],
    'Free_T4': [0.078],
    'Free_T3': [0.651],
    'pCO2_Arterial': [7.5],
    'pO2_Arterial': [7.5],
    'Lactate': [0.111],
    'Aluminum': [26.98],
}


def in_range_with_tol(val, min_val, max_val, tol=0.05):
    if min_val <= val <= max_val:
        return True
    if val < min_val and val >= min_val * (1 - tol):
        return True
    if val > max_val and val <= max_val * (1 + tol):
        return True
    return False


def clamp(val, min_val, max_val):
    if val < min_val:
        return min_val
    if val > max_val:
        return max_val
    return val


def convert_value(value, column):
    if pd.isna(value):
        return value

    if column not in reference_ranges:
        return value

    min_val, max_val = reference_ranges[column]

    # Already within range (or slight tolerance)
    if in_range_with_tol(value, min_val, max_val):
        return clamp(value, min_val, max_val)

    # Special case: HbA1c conversion from IFCC (mmol/mol)
    if column == 'HbA1c':
        # IFCC values are typically much higher than %
        if value > max_val:
            converted = (value / 10.929) + 2.15
            if in_range_with_tol(converted, min_val, max_val):
                return clamp(converted, min_val, max_val)

    # Special case: Urine Specific Gravity often recorded as 1005, 1010, etc.
    if column == 'Urine_Specific_Gravity':
        if value > max_val and value >= 10:
            converted = value * 0.001
            if in_range_with_tol(converted, min_val, max_val):
                return clamp(converted, min_val, max_val)

    # Special case: Hematocrit sometimes recorded as fraction
    if column == 'Hematocrit':
        if value < min_val and value <= 1:
            converted = value * 100.0
            if in_range_with_tol(converted, min_val, max_val):
                return clamp(converted, min_val, max_val)

    # Special case: Reticulocyte_Count sometimes recorded as fraction
    if column == 'Reticulocyte_Count':
        if value < min_val and value <= 1:
            converted = value * 100.0
            if in_range_with_tol(converted, min_val, max_val):
                return clamp(converted, min_val, max_val)

    # Apply linear conversion factors
    for factor in conversion_factors.get(column, []):
        converted = value * factor
        if in_range_with_tol(converted, min_val, max_val):
            return clamp(converted, min_val, max_val)

    return value


# Convert units
converted_df = parsed_df.copy()
for col in numeric_cols:
    converted_df[col] = converted_df[col].apply(lambda v: convert_value(v, col))

# Final check: drop rows still outside ranges (ensures output within physiological ranges)
def row_in_ranges(row):
    for col in numeric_cols:
        if col not in reference_ranges:
            continue
        val = row[col]
        if pd.isna(val):
            return False
        min_val, max_val = reference_ranges[col]
        if not (min_val <= val <= max_val):
            return False
    return True

converted_df = converted_df[converted_df.apply(row_in_ranges, axis=1)].reset_index(drop=True)

# Format to 2 decimal places
formatted_df = converted_df.copy()
for col in numeric_cols:
    formatted_df[col] = formatted_df[col].apply(lambda x: f"{x:.2f}" if pd.notna(x) else '')

# Keep patient_id as original (string)
formatted_df.to_csv(output_path, index=False)

print(f"Rows before: {before_rows}")
print(f"Rows after dropping missing: {after_rows}")
print(f"Rows after range validation: {len(formatted_df)}")
print(f"Saved to: {output_path}")

# Quick sanity: ensure no commas or scientific notation in numeric columns
sample = formatted_df[numeric_cols].head(3)
print(sample)
